steps.snippet:
:root {
  --bg: #100b07;
  --panel: #1d1510;
  --panel-2: #251a13;
  --line: #362518;
  --line-soft: #2a1d13;
  --cream: #f7ecdd;
  --muted: #b49a85;
  --gold: #f0a93b;
  --gold-soft: #ffc96b;
  --gold-deep: #b5701c;
  --danger: #e8734a;
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 22px 44px -26px rgba(0, 0, 0, 0.95);
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --speed: 180ms;
}

.grid-backdrop {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.5;
  background-image:
    linear-gradient(rgba(240, 169, 59, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(240, 169, 59, 0.05) 1px, transparent 1px);
  background-size: 46px 46px;
  mask-image: radial-gradient(70% 55% at 50% 0%, #000 30%, transparent 100%);
  -webkit-mask-image: radial-gradient(70% 55% at 50% 0%, #000 30%, transparent 100%);
}

.card {
  background: var(--panel);
  border: 1px solid var(--line-soft);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  box-shadow: var(--shadow);
  transition: border-color var(--speed) ease, transform var(--speed) ease;
}
.card:hover { border-color: var(--line); transform: translateY(-2px); }
.card.is-mine { border-color: rgba(240, 169, 59, 0.45); }

.shot { position: relative; background: #0b0705; }
.shot img { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; }

.rate { display: flex; gap: 4px; margin-top: auto; }
.drop-btn {
  background: transparent; border: 0; cursor: pointer; color: #43332a;
  padding: 4px; line-height: 0; border-radius: 8px;
  transition: color 120ms ease, transform 120ms ease;
}
.drop-btn svg { width: 26px; height: 26px; }
.drop-btn:hover, .drop-btn.is-peek { color: #7a5828; }
.drop-btn.is-on { color: var(--gold); }
.drop-btn.is-peek.is-on, .rate:hover .drop-btn.is-on { color: var(--gold-soft); }
.drop-btn:focus-visible { outline: 2px solid var(--gold-soft); outline-offset: 1px; }
.drop-btn.is-pulse { animation: pulse 420ms ease; }

@keyframes pulse {
  0% { transform: scale(1); }
  40% { transform: scale(1.28); }

@media (max-width: 760px) {
  .detail { grid-template-columns: 1fr; }
  .stats { width: 100%; margin-left: 0; }
  .seg, .search { margin-left: 0; width: 100%; }
  .seg { display: grid; grid-template-columns: repeat(3, 1fr); }
  .seg-btn { text-align: center; }
  .search input { width: 100%; min-width: 0; }
  .foot button { margin-left: 0; }
  .hero { padding-top: 34px; }
}

@media (max-width: 460px) {
  .cards { grid-template-columns: 1fr; }
  .leader img { width: 46px; height: 46px; flex-basis: 46px; }

function storage() {
  try {
    var probe = '__waffleRankProbe';
    window.localStorage.setItem(probe, '1');
    window.localStorage.removeItem(probe);
    return window.localStorage;
  } catch (err) {
    return null;
  }
}

var store = storage();

function blankState() { return { v: VERSION, ratings: {}, uploads: [], sort: 'top' }; }

function statsFor(photo) {
  var mine = state.ratings[photo.id];
  var count = photo.base.count + (mine ? 1 : 0);
  var sum = photo.base.sum + (mine || 0);
  var avg = count ? sum / count : 0;
  return { count: count, sum: sum, avg: avg, mine: mine || 0 };
}

function totals() {
  var list = photos();
  var count = 0, sum = 0;
  list.forEach(function (p) { var s = statsFor(p); count += s.count; sum += s.sum; });

function sorted() {
  var list = photos();
  var sort = state.sort;
  list.sort(function (a, b) {
    var sa = statsFor(a), sb = statsFor(b);
    if (sort === 'rated') {
      if (sb.count !== sa.count) return sb.count - sa.count;
      if (sb.avg !== sa.avg) return sb.avg - sa.avg;
    } else if (sort === 'new') {
      if (a.addedAt !== b.addedAt) return a.addedAt < b.addedAt ? 1 : -1;
    } else {
      if (sb.avg !== sa.avg) return sb.avg - sa.avg;
      if (sb.count !== sa.count) return sb.count - sa.count;
    }
    return a.name.localeCompare(b.name);
  });
  return list;
}

function readPhoto(file) {
  if (!file) return;
  if (!/^image\//.test(file.type)) { setPending(null, '', 'That file is not an image. Choose a JPG, PNG or WebP photo.'); return; }
  var reader = new FileReader();
  reader.onerror = function () { setPending(null, '', 'That photo could not be read. Try another one.'); };
  reader.onload = function () {
    var img = new Image();
    img.onerror = function () { setPending(null, '', 'That photo could not be opened. Try another one.'); };
    img.onload = function () {
      var scale = Math.min(1, MAX_EDGE / Math.max(img.width, img.height));
      var w = Math.max(1, Math.round(img.width * scale));
      var h = Math.max(1, Math.round(img.height * scale));
      var canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      canvas.getContext('2d').drawImage(img, 0, 0, w, h);
      var dataUrl;
      try { dataUrl = canvas.toDataURL('image/jpeg', JPEG_QUALITY); }
      catch (err) { setPending(null, '', 'That photo could not be prepared. Try another one.'); return; }
      setPending(dataUrl, file.name);

function rate(id, score) {
  var photo = find(id);
  if (!photo) return false;
  var was = state.ratings[id];
  if (was === score) {
    delete state.ratings[id];
    toast('Score cleared from ' + photo.name + '.');
  } else {
    state.ratings[id] = score;
    toast('Saved: ' + photo.name + ' gets ' + score + ' of 5.');
  }
  pulseTarget = { id: id, score: score };
  if (!saveState()) {
    if (was) state.ratings[id] = was; else delete state.ratings[id];
    toast('Could not save that score in this browser.');
    return false;
  }
  render();
  refreshDetail(id);
  applyPulse();
  document.dispatchEvent(new CustomEvent('wafflerank:change', {
    detail: { id: id, score: state.ratings[id] || 0, stats: statsFor(photo) }

  window.WaffleRank = {
    version: VERSION,
    getState: function () { return JSON.parse(JSON.stringify(state)); },
    photos: function () { return photos().map(function (p) {
      var s = statsFor(p);
      return { id: p.id, name: p.name, author: p.author, mine: !!p.mine,
               ratings: s.count, average: Number(s.avg.toFixed(2)), yourScore: s.mine };
    }); },
    rate: rate,
    open: openDetail,
    reset: function () { state = blankState(); saveState(); render(); },
    toast: toast
  };
})();
